$ErrorActionPreference='Stop';Set-Location $PSScriptRoot;docker info|Out-Null;if($LASTEXITCODE -ne 0){throw 'Start Docker Desktop first'};docker compose up -d atlas;if($LASTEXITCODE -ne 0){throw 'Start failed'};$port=8080;if(Test-Path .env){$line=Get-Content .env|Where-Object{$_ -match '^ATLAS_PORT='}|Select-Object -Last 1;if($line){$port=[int]($line -replace '^ATLAS_PORT=','')}};for($i=0;$i -lt 30;$i++){try{$h=Invoke-RestMethod "http://127.0.0.1:$port/api/health" -TimeoutSec 2;if($h.ok){Write-Host "Ready: http://localhost:$port";exit 0}}catch{};Start-Sleep 2};throw 'Health check timed out'
